import React from 'react';
import { Link } from 'react-router-dom';
import '../styles/Paginas.css'; // Importamos los nuevos estilos

const Mision = () => {
  return (
    <div className="pagina-container">
      <div className="pagina-box">
        <h1>Nuestra Misión</h1>
        <p>
          En PHG Soluciones Contables trabajamos con compromiso y precisión para ofrecer servicios
          contables, financieros y tributarios que impulsen el crecimiento sostenible de nuestros clientes.
        </p>
        <Link to="/" className="pagina-btn-volver">Volver al Inicio</Link>
      </div>
    </div>
  );
};

export default Mision;
